('332d91ba-790c-56ae-9235-1c0946acd0a4', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Comando SQL que define uma tabela e suas colunas.”?', '["JOIN","CREATE TABLE","HAVING","WHERE","SELECT"]'::jsonb, 1, 'CREATE TABLE: comando SQL que define uma tabela e suas colunas.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 415–417 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ed7ea533-e492-5d80-b867-71a396f0535e', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Data Science', 'Médio', 'Antes de gravar registros, a aplicação precisa declarar uma tabela com identificador e nome. Qual comando SQL usar?', '["DELETE","CREATE TABLE","GROUP BY","UPDATE","HAVING"]'::jsonb, 1, 'CREATE TABLE: comando SQL que define uma tabela e suas colunas.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 415–417 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('226b7c4b-7784-5c54-b183-712ec07c7fa3', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Comando SQL que acrescenta linhas a uma tabela.”?', '["INSERT","SELECT","UPDATE","JOIN","WHERE"]'::jsonb, 0, 'INSERT: comando SQL que acrescenta linhas a uma tabela.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 415–417 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('22bd28f8-74ca-5479-b523-c01552aff0e4', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Data Science', 'Médio', 'Uma pessoa nova deve ser incluída na tabela existente sem alterar os registros anteriores. Qual comando usar?', '["GROUP BY","DELETE","WHERE","ORDER BY","INSERT"]'::jsonb, 4, 'INSERT: comando SQL que acrescenta linhas a uma tabela.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 415–417 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ddb8546f-bbc0-5cb2-8103-526bc8cf2fbe', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Comando SQL que modifica valores de linhas existentes.”?', '["UPDATE","WHERE","DELETE","ORDER BY","GROUP BY"]'::jsonb, 0, 'UPDATE: comando SQL que modifica valores de linhas existentes.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 418 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('257338d7-7dda-523e-86f1-208f9faf921b', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Data Science', 'Médio', 'O cadastro já existe e seu número de amigos precisa ser corrigido. Qual comando SQL altera o valor armazenado?', '["ORDER BY","CREATE TABLE","GROUP BY","UPDATE","INSERT"]'::jsonb, 3, 'UPDATE: comando SQL que modifica valores de linhas existentes.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 418 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1051c642-9ecc-51d2-aef8-d50912539090', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Comando SQL que remove linhas, podendo restringi-las com uma condição.”?', '["JOIN","UPDATE","WHERE","GROUP BY","DELETE"]'::jsonb, 4, 'DELETE: comando SQL que remove linhas, podendo restringi-las com uma condição.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 419 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7837d518-a789-5680-b8d5-db800fe30e0c', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Data Science', 'Médio', 'A equipe precisa remover apenas os registros que satisfazem um filtro. Qual comando SQL realiza a exclusão das linhas?', '["ORDER BY","CREATE TABLE","DELETE","JOIN","GROUP BY"]'::jsonb, 2, 'DELETE: comando SQL que remove linhas, podendo restringi-las com uma condição.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 419 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('700ba5ec-7782-5e5e-afea-26fd10270832', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Comando SQL usado para consultar dados e expressões.”?', '["CREATE TABLE","HAVING","SELECT","INSERT","ORDER BY"]'::jsonb, 2, 'SELECT: comando SQL usado para consultar dados e expressões.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 420–421 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c5fcbc9a-ff40-5bb9-9c72-179f4659376c', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Data Science', 'Médio', 'Uma consulta deve recuperar os nomes armazenados, sem modificar a tabela. Qual comando SQL expressa essa recuperação?', '["HAVING","ORDER BY","INSERT","SELECT","GROUP BY"]'::jsonb, 3, 'SELECT: comando SQL usado para consultar dados e expressões.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 420–421 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0304965e-9be2-5464-be06-ba638c8b1eeb', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Cláusula que restringe linhas segundo uma condição antes da agregação.”?', '["DELETE","JOIN","WHERE","INSERT","GROUP BY"]'::jsonb, 2, 'WHERE: cláusula que restringe linhas segundo uma condição antes da agregação.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 420–421 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ee2846ad-8f37-5580-81bf-f48026f119a3', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Data Science', 'Médio', 'A consulta deve considerar somente usuários com mais de dez amigos antes de agrupar. Em que cláusula colocar esse filtro de linhas?', '["GROUP BY","INSERT","WHERE","CREATE TABLE","UPDATE"]'::jsonb, 2, 'WHERE: cláusula que restringe linhas segundo uma condição antes da agregação.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 420–421 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('32b15182-2c78-58e0-a2e2-bc5bafad6759', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Data Science', 'Fácil', 'No estudo de “Bases de Dados e SQL” em Grus, qual conceito corresponde à descrição: “Cláusula que reúne linhas por valores de colunas para calcular agregações por grupo.”?', '["DELETE","CREATE TABLE","WHERE","GROUP BY","ORDER BY"]'::jsonb, 3, 'GROUP BY: cláusula que reúne linhas por valores de colunas para calcular agregações por grupo.', 'GRUS, Joel. Data Science do Zero. Tradução de Welington Nascimento. Rio de Janeiro: Alta Books, 2016. ISBN 978-85-508-0387-6 (ebook). Capítulo 23: Bases de Dados e SQL, páginas 422–424 do PDF fornecido. Contexto da edição: Python 2.7. Questão original de estudo; não é questão oficial do CP-T.', false, false),
